Outputs.HeadOffset:
if (regulateHead)
    return [HeadRegulatorContact(m1aScaling * 0.5 * AveragedMechanical[0])];

/*
This keeps the output of HeadRegulator close to the current value of HeadOffset
while the HeadRegulator isn't used. This prevents overshooting when 
head regulation is enabled because HeadRegulator would output e.g. min value 
initially
*/

var setpoint := RegulatorZ.MaximalPossibleSetpoint - (1.0 - RegulatorZ.RelativeSetpoint) * 50;
var currentOutput := HeadRegulatorContact(setpoint);
var speed := 250.0; // arbitrary value, to be optimized - corresponds to adjustment speed

var direction := 0;
if (currentOutput > HeadOffset)
    direction := 1;
else if (currentOutput < HeadOffset)
    direction := -1;

var adjustmentSetpoint := setpoint - (1.0 - RegulatorZ.RelativeSetpoint) * (50 + direction * speed);
HeadRegulatorContact(adjustmentSetpoint);

return [adjustHeadOffset(HeadOffset,targetHeadOffset)];

Arriving.Z:
// check drift only after sleepTime has passed
targetHeadOffset := 0.0;

if (Scan.Time < sleepTime) {
    Scan.Arriving();
    return [];
}
// check every 2 sec
var t := sleepTime;
sleepTime := t + 2000;


regulateHead := false;

// continue Arriving if drift is above threshold
if (abs(previousZDrift - AveragedZ) > maxZDrift) {
    previousZDrift := AveragedZ;
    Scan.Arriving();
} 

if (RegulatorZ.MaximalPossibleSetpoint - (1 - RegulatorZ.RelativeSetpoint) * 50 > m1aScaling * 0.5 * AveragedMechanical[0])
    Scan.Arriving();

return [];
