MovingForward.Z:
waitForSpectrum := false;
var m0a := m1aScaling * 0.5 * AveragedMechanical[0];
var setpoint95 := RegulatorZ.MaximalPossibleSetpoint - (0.05) * 50;

if (not ((abs(UnaveragedX-x)<0.03) and (abs(UnaveragedY-y)< 0.03))){
    targetHeadOffset := -9800.0;
    regulateHead := false;
    //if (m0a < setpoint95)
    //    return [];
    return [UnaveragedZ];
}


if (RegulatorZ.MaximalPossibleSetpoint - (1 - RegulatorZ.RelativeSetpoint) * 50 > m1aScaling * 0.5 * AveragedMechanical[0]){
    regulateHead := false;
    targetHeadOffset := 0.0;
    return [];
}
// approach head with constant speed. Turn on regulator only when setpoint is almost reached.
if (m0a > setpoint95) {
    targetHeadOffset := targetHeadOffset + 12; // 5 mV per Iteration ~ 10 V per sec
    return [UnaveragedZ];
}
else{
    regulateHead := true;
    return [UnaveragedZ];
}

MovingForward.XY:
// generic 2D scan without overscanning
var x_s;
var y_s;
if (Scan.Columns == 1)
    x_s := ((PixelColumn)/Scan.Columns-0.5) * Scan.Size.X;
else
    x_s := ((PixelColumn)/(Scan.Columns-1)-0.5) * Scan.Size.X;
if (Scan.Rows == 1)
    y_s := ((PixelRow)/Scan.Rows-0.5) * Scan.Size.Y;
else
    y_s := ((PixelRow)/(Scan.Rows-1)-0.5) * Scan.Size.Y;

// var x := x_s + Scan.Center.X;
// var y := y_s + Scan.Center.Y;
var sina := sin(Scan.Rotation);
var cosa := cos(Scan.Rotation);

x := Scan.Center.X - sina * y_s + cosa * x_s;
y := Scan.Center.Y + sina * x_s + cosa * y_s;

var xCurrent := roundn(UnaveragedX,2);
var yCurrent := roundn(UnaveragedY,2);

if (((RegulatorZ.MaximalPossibleSetpoint - (1 - RegulatorZ.RelativeSetpoint) * 50 > m1aScaling * 0.5 * AveragedMechanical[0])) and (HeadOffset >= -10.0))
    Scan.WaitingForward();

return [transitionX(xCurrent,x),transitionY(yCurrent,y)];

WaitingForward.RowColumnDepth:
regulateHead := false;
targetHeadOffset := 0.0;

if (not (waitForSpectrum)){
    waitForSpectrum := true;
    Scan.SuspendToWaitForClient();
    return [];
}
if (not (Scan.IsSuspendedToWaitForClient))
    Scan.MovingBackward();
    return [PixelRow,PixelColumn,0];
return [];

MovingBackward.Z:
regulateHead := false;
waitForSpectrum := false;
targetHeadOffset := -9800.0;
if (abs(HeadOffset - targetHeadOffset) < 10.0)
    Scan.WaitingBackward();
return [UnaveragedZ];

WaitingBackward.RowColumnDepth:
if (not (waitForSpectrum)){
    waitForSpectrum := true;
    Scan.SuspendToWaitForClient();
    return [];
}
if (not (Scan.IsSuspendedToWaitForClient))
    Scan.MovingNextRow();
    return [PixelRow,PixelColumn,1];
return [];

MovingNextRow.RowColumnDepth:
regulateHead := false;
var row := PixelRow;
var col := PixelColumn + 1;
if (col == Scan.Columns) {
    col := 0;
    row += 1;
}
/*if ((Scan.Time < 1000) or (HeadOffset < 9600.0)){

    return [];
}*/

if (row == Scan.Rows)
    Scan.End();
else
    Scan.MovingForward();
return [row, col, 0];

Departing.Z:
regulateHead := false;
targetHeadOffset := 0.0;
if (abs(HeadOffset) > 5.)
    Scan.Departing();
return [];
